class Solution {
public:
    int dominantIndex(vector<int>& nums) {
        int best = 0, second = -1;
        for (int i = 1; i < (int)nums.size(); i++) {
            if (nums[i] > nums[best]) {
                second = nums[best];
                best = i;
            } else {
                second = max(second, nums[i]);
            }
        }
        return nums[best] >= 2 * second ? best : -1;
    }
};
